// Dipicu tombol Test manual -> DRY RUN. Membaca dan menghitung, tapi tidak
// menghapus satu baris pun. Pakai ini untuk mengecek angkanya masuk akal
// sebelum mengaktifkan jadwal.
return [{ json: { dry_run: true, dipicu: 'manual' } }];

// Baca CONFIG -> parameter purge STATS + token Fonnte untuk notifikasi.
//
// Kunci CONFIG yang dipakai (semua opsional, ada default):
//   stats_retention_days  angka, default 90. Umur maksimum baris berdasarkan
//                         last_reply_ts. Baris lebih tua dari ini dihapus.
//   stats_purge_dry_run   'Y' -> paksa dry run walaupun dipicu jadwal.
//                         Berguna untuk menguji tanpa menghapus apa pun.
//   admin_phone, fonnte_token
//
// CATATAN: dry_run dari mode eksekusi (Test manual) SELALU menang. CONFIG hanya
// bisa MENAMBAH pengaman (memaksa dry run), tidak pernah mematikannya.
const upstream = $input.all().map(i => i.json);

const cfg = {};
for (const r of upstream) {
  const k = String(r.key || '').trim();
  if (k) cfg[k] = (r.value !== undefined && r.value !== null) ? r.value : '';
}

const num = (k, d) => {
  const raw = cfg[k];
  if (raw === undefined || raw === '') return d;
  const n = Number(raw);
  return isNaN(n) ? d : n;
};

// Deteksi mode eksekusi. Node "Read CONFIG" mengganti isi item dengan baris
// CONFIG, jadi flag dry_run dari trigger tidak bisa mengalir lewat data --
// harus dibaca balik lewat referensi node.
//
// FAIL-CLOSED: kalau kedua node mode sama-sama tidak bisa dibaca (mis. nama
// node berubah, atau n8n mengubah perilaku referensi node yang belum
// dieksekusi), kita ANGGAP DRY RUN. Lebih baik tidak menghapus apa pun
// daripada menghapus karena sinyal yang tidak jelas.
let dryFromMode = null;
try {
  if ($('Mode: Dry Run').first().json.dry_run === true) dryFromMode = true;
} catch (e) { /* node ini tidak dieksekusi -- berarti bukan jalur manual */ }

if (dryFromMode === null) {
  try {
    if ($('Mode: Live').first().json.dry_run === false) dryFromMode = false;
  } catch (e) { /* node ini juga tidak terbaca */ }
}

if (dryFromMode === null) {
  console.warn('Mode eksekusi tidak bisa ditentukan (node "Mode: Live" maupun "Mode: Dry Run" tidak terbaca). Jatuh ke DRY RUN demi keamanan -- tidak ada baris yang dihapus. Periksa nama node kalau ini terjadi pada run terjadwal.');
  dryFromMode = true;
}

const dryFromConfig = String(cfg.stats_purge_dry_run || '').trim().toUpperCase() === 'Y';
const retentionDays = num('stats_retention_days', 90);

if (retentionDays < 30) {
  console.warn(`PERINGATAN: stats_retention_days = ${retentionDays} hari. Nilai di bawah 30 hari berisiko menghapus lead yang masih hangat. Pastikan ini memang disengaja.`);
}

return [{ json: {
  retention_days: retentionDays,
  retention_ms: retentionDays * 24 * 60 * 60 * 1000,
  dry_run: dryFromMode || dryFromConfig,
  dry_reason: dryFromMode ? 'dipicu Test manual / mode tidak terbaca' : (dryFromConfig ? 'stats_purge_dry_run=Y di CONFIG' : ''),
  admin_phone: String(cfg.admin_phone || '').trim(),
  // Token Fonnte (menggantikan kirimi user_code/secret/device_id).
  fonnte_token: String(cfg.fonnte_token || '').trim(),
} }];

// ====================================================================
// PLAN PURGE -- STATS housekeeping (retensi 90 hari default)
//
// Beda dari MSG_BUFFER: STATS TIDAK append-only. Baris di-update di tempat,
// jadi baris tua tersebar, bukan blok kontigu di atas. Karena itu di sini
// kita bangun daftar "run" (blok baris berurutan) lalu MENGHAPUS DARI BAWAH
// KE ATAS -- kalau dihapus dari atas, nomor baris di bawahnya bergeser dan
// penghapusan berikutnya akan mengenai baris yang salah.
//
// PENGAMAN:
//   1. Schema guard  -- kolom wajib harus ada, kalau tidak: berhenti total.
//   2. bot_mode OFF  -- baris yang sedang ditangani manusia TIDAK PERNAH dihapus.
//   3. ts tidak valid -> baris DIPERTAHANKAN (bukan dihapus). Defensif.
// ====================================================================
const meta = $('Parse Config Purge').first().json;
const RETENTION_MS = meta.retention_ms;
const cutoff = Date.now() - RETENTION_MS;

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.row_number !== undefined && Number(r.row_number) >= 2);

if (!rows.length) {
  return [{ json: { ...meta, total_rows: 0, to_delete: 0, kept: 0, protected_off: 0,
                    bad_ts: 0, runs: [], note: 'STATS kosong / hanya header.' } }];
}

// --- 1. Schema guard ---
const WAJIB = ['No WA', 'bot_mode', 'last_reply_ts'];
const kolom = Object.keys(rows[0]);
const hilang = WAJIB.filter(k => !kolom.includes(k));
if (hilang.length) {
  throw new Error('Schema STATS tidak sesuai -- kolom wajib hilang: ' + hilang.join(', ') +
    '. Penghapusan DIBATALKAN supaya tidak salah hapus. Kolom yang terbaca: ' + kolom.join(', '));
}

// --- 2. Nilai umur baris ---
// last_reply_ts bisa berupa epoch ms (angka) atau tanggal ISO. Dukung keduanya.
const parseTs = (raw) => {
  if (raw === undefined || raw === null || raw === '') return NaN;
  const s = String(raw).trim();
  if (/^\d{10,}$/.test(s)) return Number(s);          // epoch ms
  const p = Date.parse(s);
  return Number.isFinite(p) ? p : NaN;
};

const hapus = [];
let protectedOff = 0, badTs = 0, kept = 0;

for (const r of rows) {
  const rn = Number(r.row_number);

  // bot_mode OFF = sedang ditangani manusia -> jangan pernah disentuh.
  if (String(r.bot_mode || '').trim().toUpperCase() === 'OFF') { protectedOff++; continue; }

  const ts = parseTs(r.last_reply_ts);
  if (!Number.isFinite(ts) || ts <= 0) { badTs++; kept++; continue; }

  if (ts < cutoff) hapus.push(rn); else kept++;
}

// --- 3. Bangun run kontigu, lalu urutkan MENURUN ---
hapus.sort((a, b) => a - b);
const runs = [];
for (const rn of hapus) {
  const last = runs[runs.length - 1];
  if (last && rn === last.startRow + last.count) last.count++;
  else runs.push({ startRow: rn, count: 1 });
}
runs.sort((a, b) => b.startRow - a.startRow);   // bawah -> atas

console.log(`STATS purge: ${rows.length} baris dibaca, ${hapus.length} kedaluwarsa (${runs.length} blok), ${protectedOff} dilindungi bot_mode=OFF, ${badTs} ts tidak valid (dipertahankan).`);

return [{ json: {
  ...meta,
  total_rows: rows.length,
  to_delete: hapus.length,
  kept,
  protected_off: protectedOff,
  bad_ts: badTs,
  runs
} }];

// Pecah daftar run jadi item terpisah supaya bisa di-loop satu per satu.
// Urutan sudah MENURUN (baris terbawah dulu) dari node Plan Purge -- jangan
// diurutkan ulang di sini.
const d = $input.first().json;
return d.runs.map((r, i) => ({
  json: { ...r, urutan: i + 1, total_runs: d.runs.length, dry_run: d.dry_run }
}));

// Ringkasan hasil -- dibaca dari Plan Purge supaya jalan di kedua jalur
// (ada baris yang dihapus, maupun tidak ada sama sekali).
const d = $('Plan Purge').first().json;
const dry = d.dry_run === true;

const judul = dry ? 'STATS Purge (DRY RUN -- tidak ada yang dihapus)' : 'STATS Purge';
const alasan = dry && d.dry_reason ? ` [${d.dry_reason}]` : '';

const text = `[VIRA Personal] ${judul}${alasan}
Retensi: ${d.retention_days} hari (last_reply_ts)
Dibaca: ${d.total_rows} baris
${dry ? 'AKAN dihapus' : 'Dihapus'}: ${d.to_delete} baris (${(d.runs || []).length} blok)
Dipertahankan: ${d.kept}
Dilindungi bot_mode=OFF: ${d.protected_off}
ts tidak valid (dipertahankan): ${d.bad_ts}`;

return [{ json: { ...d, notif_text: text, dry_run: dry } }];
